add_task(async function test_positionedDialogPosition() {
  for (const test of tests) {
    const result = await setupPositioning(test);

    Assert.equal(
      result.x,
      test.result.x,
      `${test.label} - ${test.message} x value`
    );
    Assert.equal(
      result.y,
      test.result.y,
      `${test.label} - ${test.message} y value`
    );
  }
});
